      hu: ["Népszerű nyári célpont a gazdagok számára.", "Csak hajóval vagy repülővel érhető el.", "Festői városairól ismert.", "A 'Cápa' című film forgatási helyszíne volt."],
      ro: ["Destinație populară de vară pentru cei bogați.", "Accesibilă doar cu barca sau cu avionul.", "Cunoscută pentru orașele sale pitorești.", "A fost locația de filmare pentru filmul 'Fălci'."],
      en: ["Popular summer destination for the affluent.", "Accessible only by boat or air.", "Known for its picturesque towns.", "Was the filming location for the movie 'Jaws'."],
      es: ["Popular destino de verano para los adinerados.", "Accesible solo por barco o avión.", "Conocida por sus pintorescas ciudades.", "Fue lugar de rodaje de la película 'Tiburón'."],
      pt: ["Destino de verão popular para os ricos.", "Acessível apenas por barco ou avião.", "Conhecida por suas cidades pitorescas.", "Foi local de filmagem do filme 'Tubarão'."],
      fr: ["Destination estivale prisée des plus aisés.", "Accessible uniquement par bateau ou avion.", "Connue pour ses villes pittoresques.", "Lieu de tournage du film 'Les Dents de la mer'."],
