      ro: ["Un braț al Oceanului Pacific în largul coastei de sud a Alaskăi.", "Se afla pe teritoriul Statelor Unite ale Americii.", "Are un rol in identitatea regionala intre coasta de est si cea de vest."],
      en: ["A massive, highly dynamic arm of the northern Pacific Ocean.", "Renowned as a massive generator of incredibly fierce, powerful storms.", "Features a staggeringly rugged coastline with massive tidewater glaciers.", "Driven by the massive, surprisingly warm Alaska Current.", "Supports one of the most incredibly productive massive fisheries globally.", "Deeply influenced by massive, complex tectonic subduction zones."],
      es: ["Centro económico central de la región.", "Importante nudo de transporte y logística.", "Fuerte identidad cultural a través de museos locales.", "Crecimiento continuo de la población durante décadas.", "Enfoques innovadores en el desarrollo urbano.", "Diversas posibilidades para actividades al aire libre.", "Compromiso con proyectos de sostenibilidad ecológica."],
      pt: ["Centro económico central da região.", "Importante nó de transporte e logística.", "Forte identidade cultural através de museus locais.", "Crescimento populacional contínuo ao longo de décadas.", "Abordagens inovadoras no desenvolvimento urbano.", "Diversas possibilidades para atividades ao ar livre.", "Compromisso com projetos de sustentabilidade ecológica."],
      fr: ["Centre économique central de la région.", "Nœud important pour le transport et la logistique.", "Forte identité culturelle grâce aux musées locaux.", "Croissance démographique continue depuis des décennies.", "Approches innovantes en matière de développement urbain.", "Diverses possibilités d'activités de plein air.", "Engagement dans des projets de durabilité écologique."],
