      hu: ["Híres heves viharairól.", "Fontos halászterület, különösen a lazac számára.", "Jellemzőek a tengerbe borjadzó gleccserek.", "Az USA legnagyobb nemzeti erdőjével határos."],
      ro: ["Cunoscut pentru furtunile sale severe.", "Zonă importantă de pescuit, în special pentru somon.", "Caracterizat de ghețari care se varsă în mare.", "Se învecinează cu cea mai mare pădure națională din SUA."],
      en: ["Known for severe storms.", "Important fishing grounds, especially for salmon.", "Characterized by glaciers calving into the sea.", "Borders the largest US national forest."],
      es: ["Conocido por sus fuertes tormentas.", "Importantes caladeros de pesca, especialmente de salmón.", "Caracterizado por glaciares que descargan en el mar.", "Limita con el bosque nacional más grande de EE. UU."],
      pt: ["Conhecido por tempestades severas.", "Zonas de pesca importantes, especialmente de salmão.", "Caracterizado por glaciares que desaguam no mar.", "Faz fronteira com a maior floresta nacional dos EUA."],
      fr: ["Réputé pour ses violentes tempêtes.", "Zones de pêche majeures, notamment pour le saumon.", "Marqué par des glaciers qui se jettent dans la mer.", "Borde la plus grande forêt nationale des États-Unis."],
